export function base64ToBlob(dataUrl: string): Blob {
  const parts = dataUrl.split(",");
  const mime = parts[0].match(/:(.*?);/)?.[1] || "image/jpeg";
  const binary = atob(parts[1]);
  const array = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    array[i] = binary.charCodeAt(i);
  }
  return new Blob([array], { type: mime });
}

export async function getSampleFile(siteId: string): Promise<File> {
  const sample = CLINICAL_SAMPLES.find((s) => s.id === siteId);
  if (!sample) {
    throw new Error(`Unknown anatomical sub-site: ${siteId}`);
  }
  try {
    const res = await fetch(sample.url);
    if (res.ok) {
      const blob = await res.blob();
      return new File([blob], `${siteId}-sample.jpg`, { type: "image/jpeg" });
    }
  } catch {
    // Fall back to embedded base64
  }
  const blob = base64ToBlob(sample.base64);
  return new File([blob], `${siteId}-sample.jpg`, { type: "image/jpeg" });
}
